export const checkValidURL = url => {
  try {
    const urlValue = new URL(url)
    return !!urlValue
  } catch (_) {
    return false
  }
}

export const validateFormField = (type, inputValue = '') => {
  // trim the text
  const value = typeof inputValue === 'string' ? inputValue.trim() : `${inputValue}`
  switch (type) {
    case 'phone_number':
      if (value.match(/^\+?0?(62)?(62-)?[0-9]{7,17}$/)) {
        return true
      }
      return false
    case 'chasis_number':
      if (value.match(/^[0-9A-Za-z]{8,20}$/)) {
        return true
      }
      return false
    case 'machine_number':
    case 'engine_number':
      if (value.match(/^[0-9A-Za-z]{5,21}$/)) {
        return true
      }
      return false
    case 'dob':
      if (value) {
        return true
      }
      return false
    case 'ktp':
    case 'ktp_no':
      if (value.match(/^[0-9]{16}$/) || value.match(/^[0-9]{18}$/)) {
        return true
      }
      return false
    case 'npwp':
      if (value.match(/^[0-9]{15}$/)) {
        return true
      }
      return false
    case 'postal_code':
      if (value && value.match(/^[0-9]{5}$/)) {
        return true
      }
      return false
    case 'name': {
      // we are validate the name strings now
      const isNumber = value.match(/[\d+]/g)
      const isSlash = value.match(/\//g)
      const isUnderscore = value.match(/_/g)
      if (value.match(/^[A-Za-z]{1}/) && value.match(/^[A-Za-z.]{1}[\s/.\w]{0,}$/)) {
        if (isNumber && (isNumber.length > 5)) return false
        if (isSlash && (isSlash.length > 1)) return false
        if (isUnderscore && (isUnderscore.length > 1)) return false
        return true
      }
      return false
    }
    case 'string':
    case 'textarea':
    case 'input':
      if (value && value.length > 2) {
        return true
      }
      return false
    case 'amount':
    case 'number': {
      const stringValue = value.toString()
      if (stringValue.match(/^\d+$/)) {
        return true
      }
      return false
    }
    case 'email':
      if (value.match(/^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/)) {
        return true
      }
      return false
    case 'disclaimer':
    case 'radio':
    case 'radioCard':
    case 'autosuggest':
    case 'autoSearchModal':
    case 'select':
    case 'upload':
    case 'uploadFileButton':
      if (value) {
        return true
      }
      return false
    case 'uploadBulkImgButton':
      return value && value?.length
    case 'vehicle_plate_no':
    case 'plate_no': {
      const valueWithoutSpace = value.replace(/ /g, '')
      // ^[0-9]{1,4}[A-Za-z]{0,3}$
      if (valueWithoutSpace.match(/^([0-9]{1,4})([A-Za-z]{0,3})$/)) {
        return true
      }
      return false
    }
    case 'color':
      if (value && value.trim().length > 2 && value.trim().length <= 35) {
        return true
      }
      return false
    default:
      return true
  }
}

/**
 * 
 * @param {string} countryCode 
 * @param {string} number 
 * validate if the mobile number is valid or not with the given country code
 */
export const checkPhoneNumberIsValid =(number,countryCode)=>{

  if(isNaN(Number(number))){
    return false;
  }
  let flag = false;
      switch(countryCode){
        case '+62' :
          flag = number.length>10 && number.length <14;
          break;
        case '+91' :
          flag =  number.length===10;
          break;
        case '+84' :
          flag = number.length ===12;
          break;
        default :
          break;
      }
      return flag;
}

