import React from 'react'
import { connect } from 'react-redux'
import { Row, Col, Card, Form, Button, Input, Alert, Select, Spin } from 'antd'
import delayActions from '../../redux/flightDelay/actions'
import validator from '../../../helpers/validator'
import DelayWrapperStyled from './index.style'
import NumericInput from '../../../components/numericInput'
import { PhoneNumberPrefix } from '../../../helpers/constant'

const Option = Select.Option

const FormItem = Form.Item
const { createDelay, resetStateDelay } = delayActions

class FlightDelay extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      getCreateDelayStatus: '',
      loading: false,
      countryCode: '+62'
    }
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { getCreateDelayStatus } = nextProps.delay
    this.setState({
      loading: false,
      getCreateDelayStatus: getCreateDelayStatus
    })
  }

  handleMovePolicyList = () => {
    this.props.history.push('/policy')
  };

  componentDidMount = () => {
    this.props.resetStateDelay()
  };

  async validateForm () {
    return new Promise(resolve => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  handleSubmit = async e => {
    e.preventDefault()
    this.setState({ submitting: true })
    const valid = await this.validateForm()
    if (!valid) {
      this.setState({ submitting: false })
      return
    }
    const { form } = this.props
    const data = form.getFieldsValue()
    const payload = {
      ...data,
      mobile_no: `${this.state.countryCode}-${data.mobile_no}`
    }
    this.setState({ loading: true })
    this.props.createDelay(payload)
  };

  handleChange = value => {
    this.setState({ value })
  };

  handleCountryCodeSelect = e => {
    this.setState({ countryCode: e })
  };

  render () {
    const { form } = this.props
    const { getFieldDecorator } = form
    const selectBefore = (
      <Select defaultValue='+62' onSelect={this.handleCountryCodeSelect}>
        {PhoneNumberPrefix.map((prefix, index) => (
          <Option key={index} value={prefix.label}>{prefix.label}</Option>
        ))}
      </Select>
    )
    return (
      <DelayWrapperStyled>
        <Spin spinning={this.state.loading}>
          <Card>
            {this.state.getCreateDelayStatus !== '' &&
              this.state.getCreateDelayStatus !== 'success' && (
                <Alert message={this.state.getCreateDelayStatus} type='error' />
            )}
            <Form onSubmit={this.handleSubmit}>
              <Row type='flex' justify='center'>
                <Col
                  lg={12}
                  sm={24}
                  style={{
                    padding: '20px',
                    border: 'solid 1px #f6f6f6',
                    borderRadius: '10px',
                    minHeight: '460px'
                  }}
                >
                  {this.state.getCreateDelayStatus !== 'success' && (
                    <div>
                      <center>
                        <h3
                          style={{
                            background: 'whitesmoke',
                            padding: '10px',
                            width: '220px',
                            marginBottom: '30px'
                          }}
                        >
                          Create Flight Delay Policy
                        </h3>
                      </center>
                      <label className='custom-label'>Name</label>
                      <FormItem
                        style={{ fontSize: '11px' }}
                        extra='eg: John Doe'
                      >
                        {getFieldDecorator('name', {
                          rules: [
                            {
                              required: true,
                              message: 'Name can not be empty'
                            },
                            { validator: validator.validateName }
                          ]
                        })(<Input size='default' className='input-box' />)}
                      </FormItem>
                      <label className='custom-label'>Email</label>
                      <FormItem
                        style={{ fontSize: '11px' }}
                        extra='eg: johndoe@gmail.com'
                      >
                        {getFieldDecorator('email', {
                          rules: [
                            {
                              type: 'email',
                              message: 'The input is not valid E-mail!'
                            },
                            {
                              required: true,
                              message: 'Please input your E-mail!'
                            }
                          ]
                        })(<Input size='default' className='input-box' />)}
                      </FormItem>
                      <label className='custom-label'>Mobile No</label>
                      <FormItem
                        style={{ fontSize: '11px' }}
                        extra='eg: 8800165656'
                      >
                        {getFieldDecorator('mobile_no', {
                          rules: [
                            {
                              required: true,
                              message: 'Mobile No can not be empty'
                            },
                            { validator: validator.checkPhone }
                          ]
                        })(
                          <NumericInput
                            addonBefore={selectBefore}
                            onChange={this.handleChange}
                            minLength='9'
                            maxLength='12'
                          />
                        )}
                      </FormItem>
                      <label className='custom-label'>Flight Delay</label>
                      <FormItem style={{ fontSize: '11px' }} extra='eg: 1hour'>
                        {getFieldDecorator('flight_delay', {
                          rules: [
                            { required: true, message: 'Please select a value' }
                          ]
                        })(
                          <Select>
                            <Option value={0}>No Delay</Option>
                            <Option value={30}>30 Minutes</Option>
                            <Option value={60}>1 Hour</Option>
                            <Option value={120}>2 Hours </Option>
                            <Option value={150}>2 Hours 30 Minutes</Option>
                            <Option value={180}>3 Hours </Option>
                            <Option value={210}>3 Hours 30 Minutes</Option>
                            <Option value={240}>4 Hours</Option>
                            <Option value={270}>4 Hours 30 Minutes</Option>
                            <Option value={300}>5 Hours</Option>
                            <Option value={360}>6 Hours</Option>
                            <Option value={420}>7 Hours</Option>
                            <Option value={480}>8 Hours</Option>
                          </Select>
                        )}
                      </FormItem>
                      <div style={{ textAlign: 'center' }}>
                        <Button
                          key='submit'
                          type='primary'
                          htmlType='submit'
                          style={{ marginLeft: '10px' }}
                        >
                          Submit
                        </Button>
                      </div>
                    </div>
                  )}
                  {this.state.getCreateDelayStatus === 'success' && (
                    <div>
                      <p className='demo-policy-success'>
                        Delay policy has been created successfully
                      </p>
                      <center>
                        <Button onClick={this.handleMovePolicyList}>
                          View Policy Lists
                        </Button>
                      </center>
                    </div>
                  )}
                </Col>
              </Row>
            </Form>
          </Card>
        </Spin>
      </DelayWrapperStyled>
    )
  }
}

const WrappedForm = Form.create({})(FlightDelay)

export default connect(
  state => ({
    delay: state.FlightDelay
  }),
  { createDelay, resetStateDelay }
)(WrappedForm)
